package com.atube.app.recommendation.models

import com.atube.app.api.obj.StreamItem

/**
 * Represents a single video candidate in the recommendation pipeline.
 *
 * A candidate is generated by a [CandidateProvider], carries source signals
 * for the ranking engine, and is eventually converted to a [StreamItem]
 * for display in the feed.
 */
data class RecommendationCandidate(
    val video: StreamItem,
    val sourceSignals: SourceSignals,
    val generatedAt: Long = System.currentTimeMillis(),
    val source: CandidateSource
) {
    /** Stable identifier for deduplication. */
    val videoId: String
        get() = video.url?.let { url ->
            // url typically holds the video ID post-toID()
            if (url.startsWith("http")) url.substringAfter("v=").substringBefore("&")
                .ifEmpty { url } else url
        } ?: ""
}

/** Which provider contributed this candidate. */
enum class CandidateSource {
    SUBSCRIPTIONS,
    TRENDING,
    RELATED,
    SEARCH_AFFINITY,
    HISTORY_AFFINITY,
    FRESH,
    CATEGORY
}

/**
 * Signals attached to a candidate from its source.
 * These feed into the scoring formula.
 */
data class SourceSignals(
    val isFromSubscription: Boolean = false,
    val isFromTrending: Boolean = false,
    val isRelated: Boolean = false,
    val trendingRank: Int = -1,
    val relatednessScore: Float = 0f,
    val sourceCount: Int = 1
) {
    /** Multi-source boost: if a video appears in multiple sources, increase confidence. */
    val multiSourceBoost: Float
        get() = if (sourceCount > 1) (sourceCount - 1) * 0.1f else 0f
}
